import json
import numpy as np

# Input data
n_weeks = 4
n_groups = 3
group_size = 3
n_golfers = n_groups * group_size

# Model definition
model = cp.Model()

# Decision Variables
# assign[w,g,p] = golfer p is in group g in week w
assign = cp.boolvar(shape=(n_weeks, n_groups, n_golfers), name="assign")

# Constraints
# Each golfer is assigned to exactly one group per week
for w in range(n_weeks):
    for p in range(n_golfers):
        model += cp.sum(assign[w, :, p]) == 1

# Each group has exactly group_size golfers per week
for w in range(n_weeks):
    for g in range(n_groups):
        model += cp.sum(assign[w, g, :]) == group_size

# No two golfers play together more than once
for p1 in range(n_golfers):
    for p2 in range(p1 + 1, n_golfers):
        # Count how many weeks they are in the same group
        same_group = cp.sum([cp.sum(assign[w, g, p1] & assign[w, g, p2] for w in range(n_weeks) for g in range(n_groups)])
        model += same_group <= 1

# Solve and print
