from itertools import combinations

# First, find all possible combinations of three positive integers whose product is 36
possible_ages = []
for a in range(1, 37):
    for b in range(1, 37):
        for c in range(1, 37):
            if a * b * c == 36:
                possible_ages.append((a, b, c))

# Remove duplicates by sorting and using set
unique_ages = set(tuple(sorted(ages)) for ages in possible_ages)

# Now find which sums are not unique (since mathematician needed more info)
sum_counts = {}
for ages in unique_ages:
    s = sum(ages)
    if s in sum_counts:
        sum_counts[s].append(ages)
    else:
        sum_counts[s] = [ages]

# The ambiguous sums are those with multiple age combinations
ambiguous_sums = [s for s in sum_counts if len(sum_counts[s]) > 1]

# The final clue is that there is an oldest son (no twins in oldest)
# So we look for age combinations where the largest age is unique
solution = None
for s in ambiguous_sums:
    for ages in sum_counts[s]:
        if ages.count(max(ages)) == 1:
            solution = sorted(ages, reverse=True)
            break
    if solution is not None:
        break

# Print the solution
if solution is not None:
    solution_dict = {'A1': solution[0], 'A2': solution[1], 'A3': solution[2]}
    print(json.dumps(solution_dict, indent=4))
